#if UNITY_EDITOR
using System;using LastRail.Battle;using Newtonsoft.Json.Linq;using NUnit.Framework;
namespace LastRail.Tests.EditMode { public class BCombatDamageIntegrationTests {
 static BCombatFormation Formation(BCombatMode mode=BCombatMode.Solo)=>new BCombatFormation("train",mode,BCombatBattlefield.ExternalVertical,new[]{new BCombatSlot("front","op_kyle"),new BCombatSlot("cargo")});
 static BCombatHpBinding[] Bindings()=>new[]{new BCombatHpBinding("train",1000),new BCombatHpBinding("front",20),new BCombatHpBinding("cargo",100),new BCombatHpBinding("op_kyle",200)};
 static BCombatLocalModel Model(int capacity=30)=>BCombatLocalModel.CreateWithCarriageTransfer(Formation(),Bindings(),capacity,BCombatAuthority.UnitySolo);
 static CombatShieldSource Shield()=>new CombatShieldSource("op_kyle","original-shield",0);
 [Test] public void ActualCarriageLossIsCappedBefore30PercentTransfer(){var m=Model();var r=m.ApplyResolvedDamage("overkill","front",100,1);Assert.AreEqual(20,r.HpLoss);Assert.AreEqual(6,r.TransferToTrain);Assert.AreEqual(6,r.TrainHpLoss);Assert.IsTrue(r.CarriageDown);Assert.AreEqual(994,m.Hp("train"));Assert.AreEqual(200,m.Hp("op_kyle"));Assert.IsTrue(m.OperatorAlive("op_kyle"));Assert.AreEqual("op_kyle",(string)JObject.Parse(m.CaptureLocal())["definition"]["formation"]["slots"][0]["operatorId"]);}
 [Test] public void ShieldAbsorptionAndHpZeroProduceNoTransfer(){var m=Model();m.ApplyResolvedShield("shield","front",Shield(),100,100,0);var r=m.ApplyResolvedDamage("absorbed","front",100,1);Assert.AreEqual(100,r.Absorbed);Assert.AreEqual(0,r.HpLoss);Assert.AreEqual(0,r.TransferToTrain);m.ApplyResolvedDamage("fatal","front",100,2);r=m.ApplyResolvedDamage("already-down","front",100,3);Assert.AreEqual(0,r.TransferToTrain);Assert.IsFalse(r.CarriageDown);Assert.AreEqual(994,m.Hp("train"));}
 [Test] public void TrainShieldDoesNotAbsorbTransferredActualHpLoss(){var m=Model();m.ApplyResolvedShield("train-shield","train",Shield(),100,100,0);m.ApplyResolvedDamage("car","front",100,1);Assert.AreEqual(994,m.Hp("train"));var r=m.ApplyResolvedDamage("direct","train",100,2);Assert.AreEqual(100,r.Absorbed);Assert.AreEqual(0,r.HpLoss);Assert.AreEqual(994,m.Hp("train"));}
 [Test] public void OperatorAndDirectTrainDamageHaveNoSecondaryCarriageRoute(){var m=Model();var r=m.ApplyResolvedDamage("op","op_kyle",10,1);Assert.AreEqual(0,r.TransferToTrain);Assert.AreEqual(1000,m.Hp("train"));r=m.ApplyResolvedDamage("direct","train",30,2);Assert.AreEqual(0,r.TransferToTrain);Assert.AreEqual(30,r.TrainHpLoss);Assert.AreEqual(20,m.Hp("front"));Assert.AreEqual(190,m.Hp("op_kyle"));}
 [TestCase(0,0)][TestCase(1,0)][TestCase(3,0)][TestCase(4,1)][TestCase(19,5)] public void ActualLossTransferUsesExistingIntegerFloor(int loss,int transfer){var m=Model();Assert.AreEqual(transfer,m.ApplyResolvedDamage("e","cargo",loss,1).TransferToTrain);}
 [Test] public void DuplicateAndRestoredOriginalDoNotApplyAgain(){var m=Model();var r=m.ApplyResolvedDamage("e","front",100,1);var before=m.CaptureLocal();Assert.AreSame(r,m.ApplyResolvedDamage("e","front",100,1));Assert.AreEqual(before,m.CaptureLocal());var restored=BCombatLocalModel.RestoreLocal(before,Formation(),Bindings(),30,BCombatAuthority.UnitySolo);Assert.AreEqual(before,restored.CaptureLocal());var old=restored.ApplyResolvedDamage("e","front",100,1);Assert.AreEqual(6,old.TransferToTrain);Assert.AreEqual(before,restored.CaptureLocal());Assert.Throws<InvalidOperationException>(()=>restored.ApplyResolvedDamage("e","train",100,1));Assert.AreEqual(before,restored.CaptureLocal());}
 [Test] public void ShieldOriginalSourceAndExpirySurviveRestore(){var m=Model();m.ApplyResolvedShield("shield","front",Shield(),10,100,0);m.ApplyResolvedDamage("hit","front",15,1);var json=m.CaptureLocal();var restored=BCombatLocalModel.RestoreLocal(json,Formation(),Bindings(),30,BCombatAuthority.UnitySolo);Assert.AreEqual(json,restored.CaptureLocal());Assert.AreEqual(15,restored.Hp("front"));Assert.AreEqual(999,restored.Hp("train"));Assert.AreEqual(0,restored.ApplyResolvedDamage("remaining","front",1,2).Absorbed);}
 [Test] public void OriginalV1NeverAutomaticallyGainsTransferPolicy(){var old=new BCombatLocalModel(Formation(),Bindings(),30,BCombatAuthority.UnitySolo);old.ApplyResolvedSingleTargetDamage("e","front",100,1);var restored=BCombatLocalModel.RestoreLocal(old.CaptureLocal(),Formation(),Bindings(),30,BCombatAuthority.UnitySolo);Assert.AreEqual(1000,restored.Hp("train"));Assert.Throws<InvalidOperationException>(()=>restored.ApplyResolvedDamage("new","front",100,2));Assert.AreEqual("unity.combat-b.kernel-local.v1",(string)JObject.Parse(restored.CaptureLocal())["schema"]);Assert.Throws<InvalidOperationException>(()=>Model().ApplyResolvedSingleTargetDamage("e","front",100,1));}
 [Test] public void NewPolicyRejectsCoopAndWorldLocalExecution(){Assert.Throws<InvalidOperationException>(()=>BCombatLocalModel.CreateWithCarriageTransfer(Formation(BCombatMode.Coop),Bindings(),30,BCombatAuthority.UnityCoopHost));Assert.Throws<InvalidOperationException>(()=>BCombatLocalModel.CreateWithCarriageTransfer(Formation(BCombatMode.WorldSolo),Bindings(),30,BCombatAuthority.ServerWorld));}
 [Test] public void ProtectedTargetAndExpiredShieldUseExistingVitalsOnly(){var m=Model();m.ApplyResolvedShield("s","front",Shield(),10,2,0);Assert.AreEqual(0,m.ApplyResolvedDamage("protected","front",100,1,true).TransferToTrain);var r=m.ApplyResolvedDamage("expiry","front",100,2);Assert.AreEqual(0,r.Absorbed);Assert.AreEqual(6,r.TransferToTrain);}
 [Test] public void ExistingTerminalBoundaryPublishesReceiptWithoutLateHpChanges(){var m=Model();m.ApplyResolvedDamage("fatal-train","train",1000,1);var r=m.ApplyResolvedDamage("late-car","front",100,2);Assert.IsTrue(r.TrainDefeated);Assert.AreEqual(0,r.HpLoss);Assert.AreEqual(20,m.Hp("front"));r=m.ApplyResolvedDamage("late-op","op_kyle",100,3);Assert.AreEqual(0,r.HpLoss);Assert.AreEqual(200,m.Hp("op_kyle"));}
 [TestCase("hp")][TestCase("policy")][TestCase("protection")][TestCase("shield")]
 public void AlteredOriginalDamageStateCannotRestore(string bad){var m=Model();m.ApplyResolvedShield("s","front",Shield(),10,100,0);m.ApplyResolvedDamage("e","front",15,1);var saved=JObject.Parse(m.CaptureLocal());if(bad=="hp")saved["vitals"]["train"]["hp"]=1000;else if(bad=="policy")saved["definition"]["damagePolicy"]="new-policy";else if(bad=="protection")saved["events"][1]["protected"]=true;else saved["events"][0]["expiry"]=1;Assert.Throws<ArgumentException>(()=>BCombatLocalModel.RestoreLocal(saved.ToString(),Formation(),Bindings(),30,BCombatAuthority.UnitySolo));}
 [Test] public void CapacityFailureCannotApplyEitherHpRoute(){var m=Model(1);m.ApplyResolvedShield("s","front",Shield(),1,10,0);var before=m.CaptureLocal();Assert.Throws<InvalidOperationException>(()=>m.ApplyResolvedDamage("next","front",100,1));Assert.AreEqual(before,m.CaptureLocal());}
 }}
#endif
